const APP=Object.freeze({version:"4.0.0-dev.4",ruleset:"STANDARD",deck:"synthetic-v1",rounds:7,lotsPerRound:10,bidIncrementCents:5000000});
const PHASES=SEADomain.PHASES;
const MISSION_ARTWORK=Object.freeze({COMBAT:'combat',RECCE:'recce',TROOP:'troop-carrier',COMMAND:'command-post',RECOVERY:'recovery',MINE:'mine-clearing'});
function artworkAssetPath(id){if(id==='TRAIN-CAP')return 'practice/TRAIN-CAP.webp';if(Object.values(MISSION_ARTWORK).includes(id))return 'vehicles/'+id+'.webp';if(CARD_INDEX.has(id))return 'cards/'+id+'.webp';return null}
const MAX_SAFE_CENTS=BigInt(Number.MAX_SAFE_INTEGER);
const MAX_INSTRUCTOR_LEDGER_ENTRIES=210;
const {BACKUP_FORMAT,BACKUP_VERSION,MAX_BACKUP_CHARS,MAX_BACKUP_BYTES}=SEADomain;
const SEA_STORE=SEADomain.createRecoveryStore(()=>sessionStorage);
// UTF-8 needs at most three bytes per JavaScript UTF-16 code unit.
function makeBackup(role,state){return SEADomain.makeBackup(role,state,APP.version)}
function parseBackup(raw,role,validate,maxChars=MAX_BACKUP_CHARS){
 return SEADomain.parseBackup(raw,role,validate,maxChars);
}
function validCents(n){return Number.isSafeInteger(n)&&n>=0}
function parseAmount(raw){
 return SEADomain.parseAmount(raw);
}
function parseWholeDollars(raw){return SEADomain.parseWholeDollars(raw)}
function parsePercentBps(raw){return BigInt(SEADomain.parsePercentBps(raw))}
function addCents(a,b){return SEADomain.addCents(a,b)}
function profitFromBps(costCents,bps){return SEADomain.profitFromBps(costCents,bps)}
const SLOT_ORDER=SEADomain.ROUND_SLOTS;
const LABELS={CAP:{en:["Capacity","persons"],fr:["Capacité","personnes"]},MOB:{en:["Mobility","km/h"],fr:["Mobilité","km/h"]},FP:{en:["Firepower","points"],fr:["Puissance de feu","points"]},PRO:{en:["Protection","points"],fr:["Protection","points"]},COM:{en:["Communications","km"],fr:["Communications","km"]},SA:{en:["Situational awareness","ways"],fr:["Connaissance de la situation","moyens"]},REC:{en:["Recovery","ways"],fr:["Dépannage","moyens"]},MC:{en:["Mine clearing","ways"],fr:["Déminage","moyens"]}};
// Legacy role-facing shapes are adapters over the single typed canonical catalog.
const MISSIONS=Object.fromEntries(Object.entries(SEADomain.MISSIONS).map(([id,m])=>[id,{en:m.title.en,fr:m.title.fr,req:m.requirements}]));
const POOLS=Object.fromEntries([...new Set(SEADomain.ROUND_SLOTS)].map(category=>[category,SEADomain.CARDS.filter(c=>c.category===category).map(c=>[c.id,[c.title.en,c.title.fr],c.startCents/100,{...c.effects}])]));
const MISSION_IDS=SEADomain.MISSION_IDS;
function blank(){return {CAP:0,MOB:0,FP:0,PRO:0,COM:0,SA:0,REC:0,MC:0}}
function req(team){return MISSIONS[team.mission].req}
function compliant(team){return Object.entries(req(team)).every(([k,v])=>(team.totals[k]||0)>=v)}
function shortfalls(team){return Object.entries(req(team)).filter(([k,v])=>(team.totals[k]||0)<v)}
function score(team){if(!validMission(team.mission))return undefined;return SEADomain.missionScore(team.mission,{...blank(),...team.totals})}
function validMission(id){return typeof id==="string"&&MISSION_IDS.includes(id)}
function must(ok){if(!ok)throw new Error("invalid-state")}
function hasOnlyKeys(value,keys){return !!value&&typeof value==="object"&&!Array.isArray(value)&&Object.keys(value).every(key=>keys.includes(key))}
function cardIndex(){const m=new Map();for(const[cat,defs]of Object.entries(POOLS))for(const d of defs)m.set(d[0].toUpperCase(),{id:d[0],title:{en:d[1][0],fr:d[1][1]},start:d[2]*100,e:{...d[3]},cat});return m}
const CARD_INDEX=cardIndex();
function cardAt(id,round,lot){
 let c;try{c=SEADomain.cardForSlot(id,round,lot)}catch{must(false)}
 return {id:c.id,title:{...c.title},start:c.startCents,e:{...c.effects},cat:c.category,round:c.round,lot:c.lot,instance:c.instance};
}
function applyTeamSnapshot(team,next){
 const prior=new Map();for(let index=0;index<team.purchases.length;index++){const p=team.purchases[index];prior.set(p.instance,p)}
 next.purchases=next.purchases.map(p=>SEADomain.canonicalPurchaseReference(prior.get(p.instance),p));
 Object.assign(team,next);
}
function acquire(team,card,paid){
 applyTeamSnapshot(team,SEADomain.acquirePurchase(team,card,paid));
}
