function awardComparator(a,b){return SEADomain.awardComparator(a,b)}
function exactTopTie(a,b){return SEADomain.exactAwardTie(a,b)}
function awardEligible(team){return team.submitted&&SEADomain.awardEligible(team)}
function parseSessionCode(raw){return SEADomain.parseSessionCode(raw)}
function createTeams(code){const cfg=typeof code==="string"?parseSessionCode(code):code;return SEADomain.createTeams(cfg?.teamCount)}
function cleanTeam(tm,allowUnset=false){
 return SEADomain.normalizeTeam(tm,allowUnset);
}
function validateBase(x){
 return SEADomain.validateBase(x);
}
